    it = iter(data)

    N = int(next(it))

    word_to_topic = {}
    topics = []

    for _ in range(N):
        topic = next(it)
        topics.append(topic)

        K = int(next(it))
        for _ in range(K):
            word = next(it)
            word_to_topic[word] = topic

    X = int(next(it))

    counts = {topic: 0 for topic in topics}

    for _ in range(X):
        word = next(it)
        topic = word_to_topic.get(word)
        if topic is not None:
            counts[topic] += 1

    best_topic = None
    best_count = -1

    for topic in topics:
        count = counts[topic]
        if count > best_count or (count == best_count and (best_topic is None or topic < best_topic)):
            best_count = count
            best_topic = topic

    sys.stdout.buffer.write(best_topic + b'\n')

if __name__ == "__main__":
